-- Initial CardWise schema.
--
-- Conventions:
--   * Application-owned primary keys are UUIDs generated by PostgreSQL
--     (gen_random_uuid() is built in as of PostgreSQL 13).
--   * Identifiers that originate from Plaid are stored as TEXT and carry a
--     UNIQUE constraint so repeated syncs cannot create duplicate rows.
--   * Money is stored as integer cents and reward rates as integer basis
--     points (1 bp = 0.01%). Reward math must be exact and reproducible, so
--     no floating point is persisted anywhere.
--   * updated_at is maintained by a trigger rather than by each query.

CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------------
-- users
-- ---------------------------------------------------------------------------
-- Authentication is intentionally out of scope for the current phase; a user
-- is only an ownership boundary for Plaid items. Credentials, email and
-- profile columns are added in Phase 8.
CREATE TABLE users (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TRIGGER users_set_updated_at
    BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- plaid_items
-- ---------------------------------------------------------------------------
-- One row per Plaid Item (a single institution login). access_token is a
-- long-lived secret: it must never leave the backend. transaction_cursor is
-- the opaque pagination cursor used by Plaid's /transactions/sync endpoint.
CREATE TABLE plaid_items (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id            UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    plaid_item_id      TEXT NOT NULL UNIQUE,
    access_token       TEXT NOT NULL,
    transaction_cursor TEXT,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX plaid_items_user_id_idx ON plaid_items (user_id);

CREATE TRIGGER plaid_items_set_updated_at
    BEFORE UPDATE ON plaid_items
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- accounts
-- ---------------------------------------------------------------------------
-- A depository or credit account exposed by a Plaid Item. type/subtype mirror
-- Plaid's taxonomy (e.g. type='credit', subtype='credit card').
CREATE TABLE accounts (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plaid_item_id    UUID NOT NULL REFERENCES plaid_items (id) ON DELETE CASCADE,
    plaid_account_id TEXT NOT NULL UNIQUE,
    name             TEXT NOT NULL,
    official_name    TEXT,
    type             TEXT NOT NULL,
    subtype          TEXT,
    mask             TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX accounts_plaid_item_id_idx ON accounts (plaid_item_id);

CREATE TRIGGER accounts_set_updated_at
    BEFORE UPDATE ON accounts
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- transactions
-- ---------------------------------------------------------------------------
-- amount_cents follows Plaid's sign convention: positive values are money
-- leaving the account (purchases), negative values are credits/refunds.
-- category holds a normalised CardWise spending category; it is nullable
-- because categorisation happens after ingestion (Phase 3).
CREATE TABLE transactions (
    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plaid_transaction_id   TEXT NOT NULL UNIQUE,
    account_id             UUID NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    amount_cents           BIGINT NOT NULL,
    date                   DATE NOT NULL,
    name                   TEXT NOT NULL,
    merchant_name          TEXT,
    category               TEXT,
    pending                BOOLEAN NOT NULL DEFAULT FALSE,
    pending_transaction_id TEXT,
    created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at             TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Spending analysis reads transactions per account over a date range.
CREATE INDEX transactions_account_id_date_idx ON transactions (account_id, date DESC);
-- Category aggregation (Phase 3) scans by category over a date range.
CREATE INDEX transactions_category_date_idx ON transactions (category, date DESC);

CREATE TRIGGER transactions_set_updated_at
    BEFORE UPDATE ON transactions
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- credit_cards
-- ---------------------------------------------------------------------------
-- The catalogue of cards CardWise can reason about. base_reward_rate_bps is
-- the rate earned on spend that matches no bonus category (e.g. 150 = 1.5%).
CREATE TABLE credit_cards (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                 TEXT NOT NULL,
    issuer               TEXT NOT NULL,
    annual_fee_cents     INTEGER NOT NULL DEFAULT 0 CHECK (annual_fee_cents >= 0),
    base_reward_rate_bps INTEGER NOT NULL CHECK (base_reward_rate_bps >= 0),
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (issuer, name)
);

CREATE TRIGGER credit_cards_set_updated_at
    BEFORE UPDATE ON credit_cards
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- card_reward_categories
-- ---------------------------------------------------------------------------
-- Bonus earning rules for a card. reward_cap_cents is the amount of spend per
-- year that earns the bonus rate (NULL = uncapped); spend beyond the cap earns
-- the card's base rate. Cards with quarterly or rotating caps need a richer
-- model and are deliberately out of scope until the reward engine (Phase 4).
CREATE TABLE card_reward_categories (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    credit_card_id   UUID NOT NULL REFERENCES credit_cards (id) ON DELETE CASCADE,
    category         TEXT NOT NULL,
    reward_rate_bps  INTEGER NOT NULL CHECK (reward_rate_bps >= 0),
    reward_cap_cents BIGINT CHECK (reward_cap_cents > 0),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (credit_card_id, category)
);

CREATE INDEX card_reward_categories_credit_card_id_idx
    ON card_reward_categories (credit_card_id);

CREATE TRIGGER card_reward_categories_set_updated_at
    BEFORE UPDATE ON card_reward_categories
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
